function choicesOf(ids) {
	return ids.map((id) => {
		const found = ruleChoices.find((choice) => choice.id === id);
		if (!found) throw new Error(id);
		return found;
	});
}
function toneForRule(rule) {
	if (rule === "izhar" || rule === "mutlaq") return "emerald";
	if (rule === "idgham-gh" || rule === "idgham-nogh") return "gold";
	if (rule === "iqlab") return "clay";
	return "ink";
}
function ruleLabel(rule) {
	return ruleChoices.find((choice) => choice.id === rule)?.label ?? rule;
}
function spotById(id) {
	const spot = spots.find((item) => item.id === id);
	if (!spot) throw new Error(id);
	return spot;
}
function spotsForGuide(id) {
	if (id === "idgham") return spots.filter((spot) => spot.rule === "idgham-gh" || spot.rule === "idgham-nogh" || spot.rule === "mutlaq");
	return spots.filter((spot) => spot.rule === id);
}
